-- Economics: the economic systems' tax lines (DESIGN 4.17; data/econ-systems-gameeffects.xml) attached to the base
-- governments, with Economic systems and Taxes both on (economics.modinfo, criteria systems-on). Runs in each age's
-- database after that age's tax cards (load order 112), and every row selects through Governments, Traditions and
-- Modifiers, so a government or card this age doesn't hold, a DLC that isn't owned or a mod that removes either
-- skips the row instead of stopping game creation.

INSERT OR IGNORE INTO GovernmentModifiers (GovernmentType, ModifierId)
  SELECT g.GovernmentType, m.ModifierId
  FROM (SELECT 'GOVERNMENT_DESPOTISM' AS gov, 'TRADITION_ECONOMICS_HEAVY_AQ' AS card, 'MOD_ECONOMICS_SYS_DESPOTISM_HEAVY_GOLD' AS mod
    UNION ALL SELECT 'GOVERNMENT_DESPOTISM' AS gov, 'TRADITION_ECONOMICS_WAR_LEVY_AQ' AS card, 'MOD_ECONOMICS_SYS_DESPOTISM_WAR_LEVY_GOLD' AS mod
    UNION ALL SELECT 'GOVERNMENT_DESPOTISM' AS gov, 'TRADITION_ECONOMICS_WAR_LEVY_AQ' AS card, 'MOD_ECONOMICS_SYS_DESPOTISM_WAR_LEVY_HAPPINESS' AS mod
    UNION ALL SELECT 'GOVERNMENT_CLASSICAL_REPUBLIC' AS gov, 'TRADITION_ECONOMICS_LIGHT_AQ' AS card, 'MOD_ECONOMICS_SYS_CLASSICAL_REPUBLIC_LIGHT_HAPPINESS' AS mod
    UNION ALL SELECT 'GOVERNMENT_CLASSICAL_REPUBLIC' AS gov, 'TRADITION_ECONOMICS_HEAVY_AQ' AS card, 'MOD_ECONOMICS_SYS_CLASSICAL_REPUBLIC_HEAVY_HAPPINESS' AS mod
    UNION ALL SELECT 'GOVERNMENT_CLASSICAL_REPUBLIC' AS gov, 'TRADITION_ECONOMICS_WAR_LEVY_AQ' AS card, 'MOD_ECONOMICS_SYS_CLASSICAL_REPUBLIC_WAR_LEVY_HAPPINESS' AS mod
    UNION ALL SELECT 'GOVERNMENT_FEUDAL_MONARCHY' AS gov, 'TRADITION_ECONOMICS_LIGHT_EX' AS card, 'MOD_ECONOMICS_SYS_FEUDAL_MONARCHY_LIGHT_GOLD' AS mod
    UNION ALL SELECT 'GOVERNMENT_FEUDAL_MONARCHY' AS gov, 'TRADITION_ECONOMICS_HEAVY_EX' AS card, 'MOD_ECONOMICS_SYS_FEUDAL_MONARCHY_HEAVY_GOLD' AS mod
    UNION ALL SELECT 'GOVERNMENT_FEUDAL_MONARCHY' AS gov, 'TRADITION_ECONOMICS_HEAVY_EX' AS card, 'MOD_ECONOMICS_SYS_FEUDAL_MONARCHY_HEAVY_HAPPINESS' AS mod
    UNION ALL SELECT 'GOVERNMENT_FEUDAL_MONARCHY' AS gov, 'TRADITION_ECONOMICS_WAR_LEVY_EX' AS card, 'MOD_ECONOMICS_SYS_FEUDAL_MONARCHY_WAR_LEVY_GOLD' AS mod
    UNION ALL SELECT 'GOVERNMENT_FEUDAL_MONARCHY' AS gov, 'TRADITION_ECONOMICS_WAR_LEVY_EX' AS card, 'MOD_ECONOMICS_SYS_FEUDAL_MONARCHY_WAR_LEVY_HAPPINESS' AS mod
    UNION ALL SELECT 'GOVERNMENT_REVOLUTIONARY_AUTHORITARIANISM' AS gov, 'TRADITION_ECONOMICS_WAR_LEVY_EX' AS card, 'MOD_ECONOMICS_SYS_REV_AUTHORITARIANISM_WAR_LEVY_GOLD' AS mod
    UNION ALL SELECT 'GOVERNMENT_REVOLUTIONARY_AUTHORITARIANISM' AS gov, 'TRADITION_ECONOMICS_WAR_LEVY_EX' AS card, 'MOD_ECONOMICS_SYS_REV_AUTHORITARIANISM_WAR_LEVY_HAPPINESS' AS mod
    UNION ALL SELECT 'GOVERNMENT_AUTHORITARIANISM' AS gov, 'TRADITION_ECONOMICS_WAR_LEVY_MO' AS card, 'MOD_ECONOMICS_SYS_AUTHORITARIANISM_WAR_LEVY_GOLD' AS mod
    UNION ALL SELECT 'GOVERNMENT_BUREAUCRATIC_MONARCHY' AS gov, 'TRADITION_ECONOMICS_WAR_LEVY_MO' AS card, 'MOD_ECONOMICS_SYS_BUREAUCRATIC_MONARCHY_WAR_LEVY_GOLD' AS mod
    UNION ALL SELECT 'GOVERNMENT_AUTHORITARIANISM' AS gov, 'TRADITION_ECONOMICS_WAR_LEVY_MO' AS card, 'MOD_ECONOMICS_SYS_AUTHORITARIANISM_WAR_LEVY_HAPPINESS' AS mod
    UNION ALL SELECT 'GOVERNMENT_BUREAUCRATIC_MONARCHY' AS gov, 'TRADITION_ECONOMICS_WAR_LEVY_MO' AS card, 'MOD_ECONOMICS_SYS_BUREAUCRATIC_MONARCHY_WAR_LEVY_HAPPINESS' AS mod) p
  JOIN Governments g ON g.GovernmentType = p.gov
  JOIN Traditions t ON t.TraditionType = p.card
  JOIN Modifiers m ON m.ModifierId = p.mod;

-- Fascism: the branch root that unlocks Dirigisme (DESIGN 4.17 reads the ideology from it) carries Corporatist's War
-- Levy in peace, found by what it unlocks rather than by name, so a mod that moves the tradition moves the rows.
INSERT OR IGNORE INTO ProgressionTreeNodeUnlocks (ProgressionTreeNodeType, TargetKind, TargetType, UnlockDepth)
  SELECT u.ProgressionTreeNodeType, 'KIND_MODIFIER', m.ModifierId, 1
  FROM ProgressionTreeNodeUnlocks u
  JOIN Traditions t ON t.TraditionType = 'TRADITION_ECONOMICS_WAR_LEVY_MO'
  JOIN Modifiers m ON m.ModifierId IN ('MOD_ECONOMICS_SYS_FASCISM_WAR_LEVY_GOLD', 'MOD_ECONOMICS_SYS_FASCISM_WAR_LEVY_HAPPINESS')
  WHERE u.TargetType = 'TRADITION_DIRIGISME';
